//! Acceptance 4: the cloud-ops and display read faces, and the explicit
//! non-UM capability refusals, keep the Python behavior.
//!
//! The expected payloads come from `tests/fixtures/rust_console_reads_rev1.json`,
//! generated by `tests/generate_rust_console_reads_fixture.py` from the real
//! Python cloud `usagesrv.Handler`.

mod support;

use serde_json::json;

use support::*;
use um_console::cloud_ops;
use um_console::display;

#[test]
fn explicit_non_um_paths_are_capability_not_assembled() {
    let fixture = reads_fixture();
    let temp = temp();
    let console =
        start_console_with_seams(&temp, |_| {}, std::sync::Arc::new(StaticShareSeams::new()));
    let cases = fixture["capabilityExplicit"]
        .as_object()
        .expect("capability cases");
    for (path, expected) in cases {
        let response = client_request(
            console.addr,
            &ClientRequest::get(&format!("/api/console/{path}")),
        )
        .expect("request");
        assert_eq!(
            u64::from(response.status),
            expected["status"].as_u64().unwrap(),
            "{path}"
        );
        assert_eq!(response.json(), expected["body"], "{path}");
        assert_eq!(
            response.header("cache-control"),
            expected["cacheControl"].as_str(),
            "{path}"
        );
    }
}

#[test]
fn cloud_ops_matches_python_for_configured_and_unreadable_states() {
    let fixture = reads_fixture();
    let temp = temp();
    let security = temp.path().join("security.json");
    std::fs::write(
        &security,
        serde_json::to_vec(&json!({
            "format": "um-share-security-state-v1",
            "generation_floor": 3,
            "exported_at": "2026-11-15T00:00:00+00:00",
            "records": [
                {
                    "record_id": "sec-1",
                    "key_id": "key-active-1",
                    "generation": 2,
                    "action": "rotate",
                    "secret_version": 2,
                    "status": "remote_confirmed",
                    "recorded_at": "2026-11-14T00:00:00+00:00",
                    "applied_at": "2026-11-14T00:00:01+00:00",
                    "applied_generation": 2,
                    "instance_id": "instance-1",
                    "remote_confirmed_at": "2026-11-14T00:00:02+00:00",
                    "remote_receipt": {"key": "remote/2.json"},
                },
                {
                    "record_id": "sec-2",
                    "key_id": "key-active-2",
                    "generation": 3,
                    "action": "limit_lower",
                    "secret_version": 1,
                    "status": "pending",
                    "recorded_at": "2026-11-15T00:00:00+00:00",
                    "applied_at": null,
                    "applied_generation": null,
                    "instance_id": null,
                    "remote_confirmed_at": null,
                    "remote_receipt": null,
                },
            ],
        }))
        .expect("security state"),
    )
    .expect("write security state");
    let bad = temp.path().join("bad-security.json");
    std::fs::write(&bad, "{not-json").expect("bad security state");
    let cases = fixture["ac4"]["cloudOps"].as_object().expect("cloud ops");
    for (name, path) in [
        ("unconfigured", None),
        ("valid", Some(security.as_path())),
        ("invalid", Some(std::path::Path::new("bad-security.json"))),
    ] {
        let mut payload = cloud_ops::cloud_ops_status_for_tests(path);
        payload.as_object_mut().expect("object").remove("read_at");
        assert_eq!(payload, cases[name], "{name}");
    }
}

#[test]
fn cloud_ops_never_fabricates_a_safe_security_state() {
    let payload = cloud_ops::cloud_ops_status_for_tests(None);
    assert_eq!(payload["available"], json!(false));
    assert_eq!(payload["security"]["configured"], json!(false));
    assert_eq!(payload["security"]["available"], json!(false));
    assert_eq!(payload["reasons"], json!([]));
    assert_eq!(
        payload["unresolved"]["remote_export_confirmed"],
        json!("not_checked_here")
    );
    let temp = temp();
    let bad = temp.path().join("bad-security.json");
    std::fs::write(&bad, "{not-json").expect("bad security state");
    let payload = cloud_ops::cloud_ops_status_for_tests(Some(&bad));
    assert_eq!(payload["available"], json!(true));
    assert_eq!(payload["security"]["configured"], json!(true));
    assert_eq!(payload["security"]["available"], json!(false));
    assert_eq!(payload["reasons"], json!(["security_unavailable"]));
}

#[test]
fn display_session_is_honestly_unavailable_without_a_relay() {
    let fixture = reads_fixture();
    let payload = display::display_session(None);
    assert_eq!(payload, fixture["ac4"]["displaySession"]);
    assert_eq!(payload["available"], json!(false));
    assert_eq!(payload["url"], json!(null));
    assert_eq!(payload["reason"], json!("display_disabled"));
    assert_eq!(payload["operator"]["generation"], json!(0));
}

#[test]
fn display_state_maps_every_python_auth_observation() {
    let fixture = reads_fixture();
    let cases = fixture["ac4"]["displayStates"]
        .as_object()
        .expect("display states");
    for (name, expected) in cases {
        let observation = match name.as_str() {
            "unwired" => json!({
                "state": null,
                "label": null,
                "error": null,
                "primary": null,
                "observed_at": null,
                "login_window_deadline_epoch": null,
                "read_error": {
                    "code": "auth_observation_failed",
                    "message": "unwired",
                },
            }),
            "valid" => json!({
                "state": "valid",
                "label": "登录有效",
                "error": null,
                "primary": null,
                "observed_at": 1700000000,
                "login_window_deadline_epoch": 1700000600,
                "read_error": null,
            }),
            "waitingMfa" => json!({
                "state": "logging_in",
                "label": "正在登录",
                "error": "duo_prompt_waiting",
                "primary": null,
                "observed_at": 1700000000,
                "login_window_deadline_epoch": 1700000600,
                "read_error": null,
            }),
            "manual" => json!({
                "state": "failed",
                "label": "登录失败",
                "error": "manual_takeover_required:umpass_mfa_required",
                "primary": null,
                "observed_at": 1700000000,
                "login_window_deadline_epoch": 1700000600,
                "read_error": null,
            }),
            "cancelled" => json!({
                "state": "cancelled",
                "label": "本轮登录已取消",
                "error": null,
                "primary": null,
                "observed_at": 1700000000,
                "login_window_deadline_epoch": null,
                "read_error": null,
            }),
            "readError" => json!({
                "state": null,
                "label": null,
                "error": null,
                "primary": null,
                "observed_at": null,
                "login_window_deadline_epoch": null,
                "read_error": {
                    "code": "auth_observation_failed",
                    "message": "URLError: unreachable",
                },
            }),
            other => panic!("unknown display case {other}"),
        };
        assert_eq!(
            display::display_state_for_tests(Some(observation), None),
            *expected,
            "{name}"
        );
    }
}

#[test]
fn display_routes_are_read_only_and_never_return_a_path() {
    let temp = temp();
    let console =
        start_console_with_seams(&temp, |_| {}, std::sync::Arc::new(StaticShareSeams::new()));
    for target in [
        "/api/console/share-management/display-session",
        "/api/console/share-management/display-state",
        "/api/console/cloud-ops",
    ] {
        let response = client_request(console.addr, &ClientRequest::get(target)).expect("request");
        assert_eq!(response.status, 200, "{target}");
        let body = String::from_utf8_lossy(&response.body);
        assert!(!body.contains(&temp.path().to_string_lossy().to_string()));
        assert_eq!(
            response.header("cache-control"),
            Some("no-store"),
            "{target}"
        );
    }
}
